using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Globalization;using System.IO;using System.Linq;using System.Text.RegularExpressions;
namespace FortsStudio {
 public class LuaTable {
  public Dictionary<string,string> Fields=new Dictionary<string,string>();public List<string> Items=new List<string>();
  public static LuaTable Read(string s){var r=new LuaTable();if(String.IsNullOrEmpty(s))return r;int begin=s.IndexOf('{'),end=s.LastIndexOf('}');if(begin<0||end<begin)return r;int start=begin+1,depth=0;char quote='\0';for(int i=start;i<=end;i++){char c=s[i];if(quote!='\0'){if(c=='\\'){i++;continue;}if(c==quote)quote='\0';continue;}if(c=='"'||c=='\''){quote=c;continue;}if(c=='-'&&i+1<end&&s[i+1]=='-'){int newline=s.IndexOf('\n',i);if(newline<0)break;s=s.Substring(0,i)+new string(' ',newline-i)+s.Substring(newline);c=s[i];}if(c=='{')depth++;if(c=='}')depth--;if((c==','&&depth==0)||i==end){string part=s.Substring(start,i-start).Trim();if(part.Length>0){var m=Regex.Match(part,@"^([A-Za-z_]\w*)\s*=\s*([\s\S]+)$");if(m.Success)r.Fields[m.Groups[1].Value]=m.Groups[2].Value.Trim();else r.Items.Add(part);}start=i+1;}}return r;}
  public string S(string k,string fallback=""){string v;return Fields.TryGetValue(k,out v)?v.Trim().Trim('"','\''):fallback;}
  public double N(string k,double fallback=0){double d;return Double.TryParse(S(k),NumberStyles.Float,CultureInfo.InvariantCulture,out d)?d:fallback;}
  public PointF Pair(string k){var t=Read(S(k));double x=0,y=0;if(t.Items.Count>0)Double.TryParse(t.Items[0],NumberStyles.Float,CultureInfo.InvariantCulture,out x);if(t.Items.Count>1)Double.TryParse(t.Items[1],NumberStyles.Float,CultureInfo.InvariantCulture,out y);return new PointF((float)x,(float)y);}
 }
 public static class NativeModels {
  class Sprite {public List<string> Frames=new List<string>();public double Duration=.1;}
  class Node {public string Name,Sprite;public double Angle,Progress;public PointF Pivot,Offset;public List<Node> Front=new List<Node>(),Behind=new List<Node>();public static Node Read(string s){var t=LuaTable.Read(s);var n=new Node{Name=t.S("Name"),Sprite=t.S("Sprite"),Angle=t.N("Angle"),Progress=t.N("UserData"),Pivot=t.Pair("Pivot"),Offset=t.Pair("PivotOffset")};foreach(var x in LuaTable.Read(t.S("ChildrenInFront")).Items)n.Front.Add(Read(x));foreach(var x in LuaTable.Read(t.S("ChildrenBehind")).Items)n.Behind.Add(Read(x));return n;}}
  class Model {public int Bottom=-1;public Node Root;public bool? Recoil;public Dictionary<string,Sprite> Sprites=new Dictionary<string,Sprite>();public HashSet<string> AnimatedSprites=new HashSet<string>(StringComparer.Ordinal);}
  class BoundsEntry {public Model Model;public string Texture,CustomSprite;public float Scale;public double Angle;public int Progress;public RectangleF Bounds;}
  class BoundsAccumulator {
   public bool HasImage;public float Left,Top,Right,Bottom;
   readonly PointF[] points=new PointF[4];
   public void Add(Matrix transform,float width,float height){points[0]=new PointF(-width*.5f,-height*.5f);points[1]=new PointF(width*.5f,-height*.5f);points[2]=new PointF(width*.5f,height*.5f);points[3]=new PointF(-width*.5f,height*.5f);transform.TransformPoints(points);foreach(var p in points){if(!HasImage){Left=Right=p.X;Top=Bottom=p.Y;HasImage=true;}else{Left=Math.Min(Left,p.X);Right=Math.Max(Right,p.X);Top=Math.Min(Top,p.Y);Bottom=Math.Max(Bottom,p.Y);}}}
   public RectangleF Rectangle(){return HasImage?RectangleF.FromLTRB(Left,Top,Right,Bottom):RectangleF.Empty;}
  }
  static Dictionary<string,Dictionary<string,Model>> cache=new Dictionary<string,Dictionary<string,Model>>(StringComparer.Ordinal);
  static System.Runtime.CompilerServices.ConditionalWeakTable<Entity,BoundsEntry> animationBounds=new System.Runtime.CompilerServices.ConditionalWeakTable<Entity,BoundsEntry>();
  static Model Load(Entity e,string game){var t=Catalog.Get(e);game=game??"";Dictionary<string,Model> models;if(!cache.TryGetValue(game,out models)){models=new Dictionary<string,Model>(StringComparer.Ordinal);cache.Add(game,models);}Model model;if(models.TryGetValue(t.Script,out model))return model;model=new Model();models[t.Script]=model;try{string src=File.ReadAllText(Path.Combine(game,"data",t.Script));var match=Regex.Match(src,@"(?m)^\s*Root\s*=");if(match.Success)model.Root=Node.Read(Catalog.Balanced(src,src.IndexOf('{',match.Index)));match=Regex.Match(src,@"(?m)^\s*Sprites\s*=");if(match.Success){var sprites=LuaTable.Read(Catalog.Balanced(src,src.IndexOf('{',match.Index)));foreach(string item in sprites.Items){var st=LuaTable.Read(item);var states=LuaTable.Read(st.S("States"));var normal=LuaTable.Read(states.S("Normal"));var frames=LuaTable.Read(normal.S("Frames"));var sprite=new Sprite{Duration=Math.Max(.01,frames.N("duration",.1))};foreach(var frame in frames.Items){string path=LuaTable.Read(frame).S("texture");if(path.Length>0)sprite.Frames.Add(path);}model.Sprites[st.S("Name")]=sprite;}}}catch{}FindAnimatedSprites(model,model.Root);return model;}
  static void FindAnimatedSprites(Model model,Node node){if(node==null)return;Sprite sprite;if(model.Sprites.TryGetValue(node.Sprite,out sprite)&&sprite.Frames.Count>1)model.AnimatedSprites.Add(node.Sprite);foreach(var child in node.Behind)FindAnimatedSprites(model,child);foreach(var child in node.Front)FindAnimatedSprites(model,child);}
  public static bool IsAnimated(Entity e,string game){var model=Load(e,game);if(model.AnimatedSprites.Count==0)return false;if(e.Texture.Length==0)return true;string customSprite=Catalog.Get(e).Sprite;foreach(string sprite in model.AnimatedSprites)if(sprite!=customSprite)return true;return false;}
  public static bool HasRecoil(Entity e,string game){var model=Load(e,game);if(!model.Recoil.HasValue)model.Recoil=HasBarrel(model.Root);return model.Recoil.Value;}
  static bool HasBarrel(Node node){if(node==null)return false;if(node.Name=="Barrel")return true;foreach(var child in node.Behind)if(HasBarrel(child))return true;foreach(var child in node.Front)if(HasBarrel(child))return true;return false;}
  static Bitmap RootImage(Model model,string game){Sprite sprite;return model.Sprites.TryGetValue(model.Root.Sprite,out sprite)&&sprite.Frames.Count>0?Assets.Image(sprite.Frames[0],game):null;}
  static float RootTranslation(Model model,Bitmap image){if(image==null)return 0;if(model.Bottom<0){model.Bottom=image.Height;for(int y=image.Height-1;y>=0;y--){bool found=false;for(int x=0;x<image.Width;x+=3)if(image.GetPixel(x,y).A>45){found=true;break;}if(found){model.Bottom=y+1;break;}}}return (float)(image.Height*.5-model.Bottom-model.Root.Pivot.Y*image.Height);}
  static Bitmap NodeImage(Model model,Node node,Entity e,string game,double time){if(e.Texture.Length>0&&node.Sprite==Catalog.Get(e).Sprite)return Assets.Image(e.Texture,game);Sprite sprite;if(!model.Sprites.TryGetValue(node.Sprite,out sprite)||sprite.Frames.Count==0)return null;int frame=(int)(time/sprite.Duration)%sprite.Frames.Count;if(frame<0)frame+=sprite.Frames.Count;return Assets.Image(sprite.Frames[frame],game);}
  public static bool Draw(Graphics g,Entity e,string game,PointF pos,float scale,double angle,int progress,double time,double recoil){var model=Load(e,game);if(model.Root==null)return false;var state=g.Save();g.TranslateTransform(pos.X,pos.Y);g.ScaleTransform(scale*.5f,scale*.5f);var rootImage=RootImage(model,game);if(rootImage!=null)g.TranslateTransform(0,RootTranslation(model,rootImage));DrawNode(g,model,model.Root,e,game,rootImage==null?0:rootImage.Width,rootImage==null?0:rootImage.Height,angle,progress,time,recoil);g.Restore(state);return true;}
  // Coordinates are relative to the same origin and scale accepted by Draw.
  // Both recoil endpoints are included because cached world tiles may draw the
  // model at any point in its recoil animation without recomputing this box.
  public static bool TryBounds(Entity e,string game,float scale,double angle,int progress,double time,out RectangleF bounds){var model=Load(e,game);bounds=RectangleF.Empty;if(model.Root==null)return false;bounds=ModelBounds(model,e,game,scale,angle,progress,time,false);return true;}
  // Stable animation bounds are used by world tiles. A frame with a larger
  // canvas must not be culled using the dimensions of its smaller predecessor.
  public static bool TryAnimationBounds(Entity e,string game,float scale,double angle,int progress,out RectangleF bounds){var model=Load(e,game);bounds=RectangleF.Empty;if(model.Root==null)return false;string customSprite=Catalog.Get(e).Sprite;BoundsEntry entry;if(animationBounds.TryGetValue(e,out entry)&&Object.ReferenceEquals(entry.Model,model)&&Object.ReferenceEquals(entry.Texture,e.Texture)&&entry.CustomSprite==customSprite&&entry.Scale==scale&&entry.Angle==angle&&entry.Progress==progress){bounds=entry.Bounds;return true;}bounds=ModelBounds(model,e,game,scale,angle,progress,0,true);animationBounds.Remove(e);animationBounds.Add(e,new BoundsEntry{Model=model,Texture=e.Texture,CustomSprite=customSprite,Scale=scale,Angle=angle,Progress=progress,Bounds=bounds});return true;}
  static RectangleF ModelBounds(Model model,Entity e,string game,float scale,double angle,int progress,double time,bool allFrames){var rootImage=RootImage(model,game);var box=new BoundsAccumulator();using(var zero=new Matrix()){zero.Scale(scale*.5f,scale*.5f);if(rootImage!=null)zero.Translate(0,RootTranslation(model,rootImage));using(var full=zero.Clone())BoundsNode(model,model.Root,e,game,rootImage==null?0:rootImage.Width,rootImage==null?0:rootImage.Height,angle,progress,time,allFrames,zero,full,box);}return box.Rectangle();}
  static List<SizeF> ImageSizes(Model model,Node node,Entity e,string game,double time,bool allFrames){var sizes=new List<SizeF>();if(!allFrames||e.Texture.Length>0&&node.Sprite==Catalog.Get(e).Sprite){var image=NodeImage(model,node,e,game,time);if(image!=null)sizes.Add(new SizeF(image.Width,image.Height));return sizes;}Sprite sprite;if(model.Sprites.TryGetValue(node.Sprite,out sprite))foreach(string frame in sprite.Frames){var image=Assets.Image(frame,game);var size=image==null?SizeF.Empty:new SizeF(image.Width,image.Height);if(!sizes.Contains(size))sizes.Add(size);}return sizes;}
  static void BoundsNode(Model model,Node node,Entity e,string game,float parentW,float parentH,double aim,int progress,double time,bool allFrames,Matrix parentZero,Matrix parentFull,BoundsAccumulator box){if(node.Progress>progress)return;var sizes=ImageSizes(model,node,e,game,time,allFrames);if(sizes.Count==0)sizes.Add(SizeF.Empty);foreach(var size in sizes){bool hasImage=size.Width>0&&size.Height>0;float w=hasImage?size.Width:parentW,h=hasImage?size.Height:parentH;using(var zero=parentZero.Clone())using(var full=parentFull.Clone()){float x=node.Pivot.X*parentW+node.Offset.X*w,y=node.Pivot.Y*parentH+node.Offset.Y*h;float rotation=(float)(node.Angle+(node.Name=="Head"?-aim:0));zero.Translate(x,y);full.Translate(x,y);zero.Rotate(rotation);full.Rotate(rotation);if(node.Name=="Barrel")full.Translate((float)-Math.Min(25,w*.15),0);if(hasImage){box.Add(zero,w,h);box.Add(full,w,h);}foreach(var child in node.Behind)BoundsNode(model,child,e,game,w,h,aim,progress,time,allFrames,zero,full,box);foreach(var child in node.Front)BoundsNode(model,child,e,game,w,h,aim,progress,time,allFrames,zero,full,box);}}}
  static void DrawNode(Graphics g,Model model,Node node,Entity e,string game,float parentW,float parentH,double aim,int progress,double time,double recoil){if(node.Progress>progress)return;string name=node.Name;Bitmap im=NodeImage(model,node,e,game,time);float w=im==null?parentW:im.Width,h=im==null?parentH:im.Height;PointF pivot=node.Pivot,offset=node.Offset;var state=g.Save();g.TranslateTransform(pivot.X*parentW+offset.X*w,pivot.Y*parentH+offset.Y*h);g.RotateTransform((float)(node.Angle+(name=="Head"?-aim:0)));if(name=="Barrel")g.TranslateTransform((float)(-recoil*Math.Min(25,w*.15)),0);float x=-.5f*w,y=-.5f*h;
   foreach(var child in node.Behind)DrawNode(g,model,child,e,game,w,h,aim,progress,time,recoil);if(im!=null)g.DrawImage(im,x,y,w,h);foreach(var child in node.Front)DrawNode(g,model,child,e,game,w,h,aim,progress,time,recoil);g.Restore(state);
  }
 }
}
